function init(){gls.forEach((gl,index)=>{if(!gl)return;try{initGL(gl)}catch(e){console.error(e);let message=`3D renderer could not initialize: ${e.message}`;document.querySelectorAll('.viewport')[index].insertAdjacentHTML('beforeend',`<div class="webgl-error">${message}</div>`)}})}
function itemSettled(i){let b=physicsBodies[i];return b.mode==='dynamic'&&Math.hypot(...b.vel)<.04}
function updateUI(){let phase=[...phases].reverse().find(p=>time>=p.t)||phases[0],operation=operationAt(time),count=inventory.filter((_,i)=>itemSettled(i)).length;$('#overview-stage').textContent=operation.item?`${operation.item.name.toUpperCase()} · ${operation.stage.toUpperCase()}`:phase.stage;$('#operator-stage').textContent=firstPerson?'EGOCENTRIC · HANDS IN VIEW':'OPERATOR · EYE LEVEL';$('#overview-clock').textContent=`00:${String(Math.floor(time)).padStart(2,'0')}.${Math.floor(time%1*10)}`;$('#task-title').textContent=phase.title;$('#task-copy').textContent=phase.copy;$('#action-title').textContent=operation.item?operation.label:phase.action;$('#action-copy').textContent=`${operation.item?operation.detail:phase.copy} Simulation time ${time.toFixed(1)} seconds.`;$('#distance').textContent=`${routeDistance(time).toFixed(1)} m`;$('#packed').textContent=`${count} / 7`;$('#contacts').textContent=physicsBodies.filter(b=>b.mode==='dynamic').length;$('#clearance').textContent=spatialClearAt(time)&&packedLayoutClear()?'CLEAR':'CONTACT';$('#physics-state').textContent=balanceStable?'STABLE':'RECOVERING';$('#progress-fill').style.width=`${count/7*100}%`;$('#inventory').innerHTML=inventory.map((i,j)=>`<span class="item-chip ${itemSettled(j)?'done':''}">${itemSettled(j)?'✓ ':''}${i.name}</span>`).join('');let active=[...chapters].reverse().find(c=>time>=c[1])||chapters[0];document.querySelectorAll('.chapters button').forEach(b=>b.setAttribute('aria-current',Number(b.dataset.time)===active[1]?'true':'false'));const stage=operation.item?operation.stage:operation.stage==='walk'?'approach':null,order=['approach','reach','grip','lift','carry','align','lower','release','settle'],idx=order.indexOf(stage);document.querySelectorAll('#stage-rail [data-stage]').forEach(el=>{const i=order.indexOf(el.dataset.stage);el.toggleAttribute('data-done',idx>=0&&i<idx);if(i===idx)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});$('#sequence-status').textContent=time>=duration?'RUN COMPLETE · END-STATE CHECKS UNVERIFIED':playing?'RUNNING · BOTH VIEWS SYNCED':time>0?'PAUSED · BOTH VIEWS SYNCED':'READY TO REPLAY';$('#play').innerHTML=playing?'Ⅱ <span>Pause sequence</span>':'▶ <span>Play sequence</span>'}
function setTime(t){time=clamp(t,0,duration);advancePhysics(time);timeline.value=time;render(0);render(1);updateUI()}
chapters.forEach(([label,t])=>{let b=document.createElement('button');b.dataset.time=t;b.textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}  ${label}`;b.onclick=()=>{playing=false;setTime(t)};$('#chapters').appendChild(b)});
$('#play').onclick=()=>{if(time>=duration)setTime(0);playing=!playing;updateUI()};$('#restart').onclick=()=>{playing=false;setTime(0)};$('#speed').onchange=e=>speed=Number(e.target.value);timeline.oninput=e=>{playing=false;setTime(Number(e.target.value))};$('#view-mode').onclick=e=>{firstPerson=!firstPerson;e.currentTarget.setAttribute('aria-pressed',String(firstPerson));render(1)};
$('#evidence').textContent=JSON.stringify(JSON.parse($('#run-evidence-data').textContent),null,2);
function showPlaybackError(error){playing=false;console.error(error);updateUI();$('#action-copy').textContent=`Playback stopped: ${error.message||error}`}
function advancePlayback(){if(!playing)return;try{time=Math.min(duration,time+.05*speed);setTime(time);if(time>=duration)playing=false;updateUI()}catch(error){showPlaybackError(error)}}
init();
if(typeof ResizeObserver!=='undefined'){new ResizeObserver(()=>{render(0);render(1)}).observe(canvases[0]);new ResizeObserver(()=>render(1)).observe(canvases[1])}else{window.addEventListener('resize',()=>{render(0);render(1)})}
try{setTime(0)}catch(error){showPlaybackError(error)}
setInterval(advancePlayback,50);
window.addEventListener('error',event=>{showPlaybackError(event.error||event.message||'Unknown page error')});
